<h1 class="h">Nastavení firmy</h1><div class="sub">Údaje se používají v dokladech a PDF.</div><form class="form" method="post"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="field"><label>Název firmy</label><input name="name" value="<?=View::e($workspace['name'])?>" required></div><div class="row"><div class="field"><label>IČO</label><input name="ico" value="<?=View::e($workspace['ico'])?>"></div><div class="field"><label>DIČ</label><input name="dic" value="<?=View::e($workspace['dic'])?>"></div></div><div class="row"><div class="field"><label>Ulice</label><input name="street" value="<?=View::e($workspace['street'])?>"></div><div class="field"><label>Město</label><input name="city" value="<?=View::e($workspace['city'])?>"></div></div><div class="row"><div class="field"><label>PSČ</label><input name="zip" value="<?=View::e($workspace['zip'])?>"></div><div class="field"><label>Bankovní účet</label><input name="bank_account" value="<?=View::e($workspace['bank_account'])?>"></div></div><div class="row"><div class="field"><label>E-mail</label><input name="email" value="<?=View::e($workspace['email'])?>"></div><div class="field"><label>Telefon</label><input name="phone" value="<?=View::e($workspace['phone'])?>"></div></div><div class="card"><h3>Automatické e-maily</h3><p>Odesílatel: <b><?=View::e($workspace['email_localpart']??'firma')?>@<?=View::e($mail_domain)?></b></p><div class="field"><label>Adresa před @</label><input name="email_localpart" value="<?=View::e($workspace['email_localpart']??'')?>" pattern="[A-Za-z0-9.-]+"></div><p><label><input type="checkbox" name="mail_enabled" <?=!empty($workspace['mail_enabled'])?'checked':''?>> Posílat e-maily za mě</label></p><div class="row"><label><input type="checkbox" name="mail_invoices" <?=!empty($workspace['mail_invoices'])?'checked':''?>> Faktury</label><label><input type="checkbox" name="mail_reminders" <?=!empty($workspace['mail_reminders'])?'checked':''?>> Upomínky</label><label><input type="checkbox" name="mail_receipts" <?=!empty($workspace['mail_receipts'])?'checked':''?>> Potvrzení plateb</label><label><input type="checkbox" name="mail_offers" <?=!empty($workspace['mail_offers'])?'checked':''?>> Nabídky</label></div></div><button class="btn primary">Uložit</button></form>
